declare(strict_types=1);require_once __DIR__.'/operations.php';header('Content-Type: application/json; charset=utf-8');require_role('owner_admin');if(empty($_SESSION['epi_bookkeeping_review_csrf']))$_SESSION['epi_bookkeeping_review_csrf']=bin2hex(random_bytes(32));if($_SERVER['REQUEST_METHOD']==='GET'){echo json_encode(['ok'=>true,'csrf_token'=>(string)$_SESSION['epi_bookkeeping_review_csrf']]);exit;}
try{if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('POST required.');$session=(string)($_SESSION['epi_bookkeeping_review_csrf']??'');$given=(string)($_POST['csrf_token']??'');if($session===''||$given===''||!hash_equals($session,$given))throw new RuntimeException('Your session expired. Refresh and try again.');$decision=trim((string)($_POST['decision']??''));$allowed=['pending_review','confirmed_employee_error','confirmed_system_error','confirmed_pos_sync_error','confirmed_owner_instruction','external_dependency','excused','corrected','dismissed'];if(!in_array($decision,$allowed,true))throw new RuntimeException('Choose a valid review decision.');$reason=trim((string)($_POST['reason']??''));if($reason==='')throw new RuntimeException('A review reason is required.');$evidence=trim((string)($_POST['evidence_uuid']??''));if($evidence==='')throw new RuntimeException('Evidence ID is required.');$actor=ops_current_employee_id();db()->prepare('INSERT INTO epi_bookkeeping_reviews(evidence_uuid,reviewer_id,decision,reason) VALUES(?,?,?,?)')->execute([$evidence,$actor,$decision,substr($reason,0,1500)]);ops_activity_log('bookkeeping_evidence_reviewed','epi_bookkeeping_review',(int)db()->lastInsertId(),['evidence_uuid'=>$evidence,'decision'=>$decision,'reviewer_id'=>$actor,'immutable_review'=>true]);echo json_encode(['ok'=>true,'message'=>'Review recorded. Original evidence was retained.'],JSON_UNESCAPED_SLASHES);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_SLASHES);}
